WITH cleaned AS (SELECT *, CAST(salary AS INT) AS salary_int, UPPER(full_name) AS full_name_upper FROM employees WHERE hire_date > DATE '2023-07-16') SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, CASE WHEN salary_int >= 78 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_int_tier, AVG(salary_int) AS avg_salary_int, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, COUNT(CASE WHEN level = 'L1' THEN 1 END) AS l1_count, COUNT_IF(job_title = 'Director') AS director_events FROM cleaned GROUP BY DATE_TRUNC('QUARTER', hire_date), CASE WHEN salary_int >= 78 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING COUNT_IF(job_title = 'Director') >= 1 ORDER BY salary_int_tier DESC NULLS FIRST;
